    list: { gap: spacing.xs },
    listRow: { flexDirection: "row", alignItems: "flex-start", gap: spacing.sm, paddingLeft: spacing.xs },
    marker: { ...type.body, ...type.mono, color: colors.primaryText, minWidth: 24 },
    listBody: { flex: 1, minWidth: 0 },
