import type { BenchmarkHistoryRecord, EvolutionHistoryRecord } from "@keating/learner-contracts";

export interface EvaluationTrendPoint {
  id: string;
  kind: "benchmark" | "evolution";
  score: number;
  createdAt: string;
  x: number;
  y: number;
}

export interface EvaluationTrend {
  points: EvaluationTrendPoint[];
  benchmarkPoints: EvaluationTrendPoint[];
  evolutionPoints: EvaluationTrendPoint[];
  latestBenchmark?: BenchmarkHistoryRecord;
  latestEvolution?: EvolutionHistoryRecord;
  hasMeaningfulScores: boolean;
}

const LEFT = 28;
const RIGHT = 310;
const TOP = 10;
const BOTTOM = 122;

/** Pure projection of actual run history; it never derives a score from learner activity. */
export function buildEvaluationTrend(
  benchmarks: readonly BenchmarkHistoryRecord[],
  evolutions: readonly EvolutionHistoryRecord[],
): EvaluationTrend {
  const ordered = [
    ...benchmarks.map((record) => ({ id: record.id, kind: "benchmark" as const, score: record.score, createdAt: record.createdAt })),
    ...evolutions.map((record) => ({ id: record.id, kind: "evolution" as const, score: record.bestScore, createdAt: record.createdAt })),
  ].sort((left, right) => left.createdAt.localeCompare(right.createdAt) || left.id.localeCompare(right.id));
  const timestamps = ordered.map((record) => Date.parse(record.createdAt));
  const minimum = timestamps.length ? Math.min(...timestamps) : 0;
  const maximum = timestamps.length ? Math.max(...timestamps) : minimum;
  const span = Math.max(maximum - minimum, 1);
  const points = ordered.map((record) => ({
    ...record,
    x: LEFT + ((Date.parse(record.createdAt) - minimum) / span) * (RIGHT - LEFT),
    y: BOTTOM - (record.score / 100) * (BOTTOM - TOP),
  }));
  const byDate = <T extends { createdAt: string; id: string }>(records: readonly T[]) =>
    [...records].sort((left, right) => left.createdAt.localeCompare(right.createdAt) || left.id.localeCompare(right.id));
  const orderedBenchmarks = byDate(benchmarks);
  const orderedEvolutions = byDate(evolutions);
  return {
    points,
    benchmarkPoints: points.filter((point) => point.kind === "benchmark"),
    evolutionPoints: points.filter((point) => point.kind === "evolution"),
    latestBenchmark: orderedBenchmarks.at(-1),
    latestEvolution: orderedEvolutions.at(-1),
    hasMeaningfulScores: points.some((point) => point.score !== 0),
  };
}

export function evaluationPath(points: readonly EvaluationTrendPoint[]): string {
  return points.map((point, index) => `${index === 0 ? "M" : "L"} ${point.x.toFixed(2)} ${point.y.toFixed(2)}`).join(" ");
}
import type {
  LearnerFeedbackEvent,
  LearnerMessage,
  LearnerSession,
  PortableLearnerData,
} from "@keating/learner-contracts";

export type TrainingMessage = { role: "system" | "user" | "assistant"; content: string };
export type TrainingQualityStatus = "accepted" | "unscored" | "review" | "rejected" | "reference";

export interface CanonicalTrainingRecord {
  schemaVersion: 2;
  id: string;
  split: "train" | "validation";
  task: "supervised-finetuning" | "preference-learning" | "reference";
  source: {
    type: "artifact" | "session";
    kind: string;
    topic?: string;
    sessionId?: string;
    sessionTitle?: string;
    messageTimestamp?: number;
    model?: { provider: string; id: string; name?: string };
  };
  messages: TrainingMessage[];
  prompt: TrainingMessage[];
  completion: string;
  quality: {
    status: TrainingQualityStatus;
    recommendedForSft: boolean;
    scored: boolean;
    reward?: number;
    signals?: Record<string, unknown>;
  };
  metrics: {
    promptCharacters: number;
    completionCharacters: number;
    messageCount: number;
  };
}

export interface NativeFineTuneExportResult {
  canonicalJsonl: string;
  chatmlJsonl: string;
  alpacaJsonl: string;
  rewardedJsonl?: string;
  ktoJsonl?: string;
  preferenceJsonl?: string;
  dpoTextJsonl?: string;
  grpoPromptsJsonl?: string;
  manifestJson: string;
  recordCount: number;
  exampleCount: number;
  skippedCount: number;
  redactionCount: number;
}

export interface NativeFineTuneExportOptions {
  redact?: boolean;
  minimumAssistantCharacters?: number;
  now?: Date;
}

interface Candidate {
  id: string;
  source: CanonicalTrainingRecord["source"];
  messages: TrainingMessage[];
  quality: CanonicalTrainingRecord["quality"];
}

const SECRET_PATTERNS: RegExp[] = [
  /\bsk-ant-[A-Za-z0-9_-]{12,}\b/g,
  /\bsk-[A-Za-z0-9_-]{12,}\b/g,
  /\bAIza[A-Za-z0-9_-]{16,}\b/g,
  /\bghp_[A-Za-z0-9_]{12,}\b/g,
  /\bBearer\s+[A-Za-z0-9._-]{12,}\b/gi,
  /^[A-Z][A-Z0-9_]*_API_KEY\s*=\s*.+$/gm,
  /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi,
];

function stableHash(value: string): number {
  let hash = 0x811c9dc5;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193);
  }
  return hash >>> 0;
}

function safeId(value: string): string {
  return value.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 80) || "item";
}

function toJsonl(values: readonly unknown[]): string {
  return values.length ? `${values.map((value) => JSON.stringify(value)).join("\n")}\n` : "";
}

function redactText(input: string, enabled: boolean): { text: string; count: number } {
  if (!enabled) return { text: input, count: 0 };
  let text = input;
  let count = 0;
  for (const pattern of SECRET_PATTERNS) {
    text = text.replace(pattern, () => {
      count += 1;
      return "[REDACTED]";
    });
  }
  return { text, count };
}

function artifactInstruction(kind: string, title: string): string {
  switch (kind) {
    case "study-plan": return `Create a Keating-style Socratic lesson plan for ${title}.`;
    case "lesson-map": return `Create a Mermaid concept map for ${title}.`;
    case "quiz": return `Create retrieval practice and an answer key for ${title}.`;
    case "animation": return `Create a teaching animation storyboard for ${title}.`;
    case "verification": return `Create a verification checklist before teaching ${title}.`;
    default: return `Create a Keating teaching artifact for ${title}.`;
  }
}

function feedbackByMessage(events: readonly LearnerFeedbackEvent[]): Map<string, LearnerFeedbackEvent> {
  const result = new Map<string, LearnerFeedbackEvent>();
  for (const event of events) {
    const prior = result.get(event.messageId);
    if (!prior || prior.createdAt < event.createdAt || (prior.createdAt === event.createdAt && prior.id < event.id)) {
      result.set(event.messageId, event);
    }
  }
  return result;
}

function qualityForFeedback(event?: LearnerFeedbackEvent): CanonicalTrainingRecord["quality"] {
  if (!event) return { status: "unscored", recommendedForSft: false, scored: false };
  const accepted = event.rating === "helpful";
  return {
    status: accepted ? "accepted" : "rejected",
    recommendedForSft: accepted,
    scored: true,
    reward: accepted ? 1 : 0,
    signals: { explicit: { feedbackId: event.id, rating: event.rating } },
  };
}

function sessionCandidates(
  session: LearnerSession,
  latestFeedback: ReadonlyMap<string, LearnerFeedbackEvent>,
  minimumAssistantCharacters: number,
  redact: boolean,
  counters: { skipped: number; redactions: number },
): Candidate[] {
  const candidates: Candidate[] = [];
  const relevant = session.messages.filter((message) => message.role === "user" || message.role === "assistant");
  for (let index = 0; index < relevant.length - 1; index += 1) {
    const user = relevant[index];
    const assistant = relevant[index + 1];
    if (user?.role !== "user" || assistant?.role !== "assistant") continue;
    if (!user.content.trim() || assistant.content.trim().length < minimumAssistantCharacters) {
      counters.skipped += 1;
      continue;
    }
    const redactedUser = redactText(user.content.trim(), redact);
    const redactedAssistant = redactText(assistant.content.trim(), redact);
    counters.redactions += redactedUser.count + redactedAssistant.count;
    candidates.push({
      id: `session-${safeId(session.id)}-${safeId(assistant.id)}`,
      source: {
        type: "session",
        kind: "conversation",
        topic: session.title,
        sessionId: session.id,
        sessionTitle: session.title,
        messageTimestamp: Date.parse(assistant.createdAt),
        model: session.model,
      },
      messages: [
        { role: "user", content: redactedUser.text },
        { role: "assistant", content: redactedAssistant.text },
      ],
      quality: qualityForFeedback(latestFeedback.get(assistant.id)),
    });
  }
  return candidates;
}

function canonicalRecord(candidate: Candidate): CanonicalTrainingRecord {
  const completion = candidate.messages.at(-1)?.content ?? "";
  const prompt = candidate.messages.slice(0, -1);
  const fingerprint = JSON.stringify([
    ...prompt.map((message) => [message.role, message.content.trim()]),
    ["assistant", completion.trim()],
  ]);
  const sourceGroup = candidate.source.sessionId ?? candidate.id;
  return {
    schemaVersion: 2,
    id: `${candidate.id}-${stableHash(fingerprint).toString(36)}`,
    split: stableHash(sourceGroup) % 10 === 0 ? "validation" : "train",
    task: candidate.quality.status === "rejected" ? "preference-learning" : "supervised-finetuning",
    source: candidate.source,
    messages: candidate.messages,
    prompt,
    completion,
    quality: candidate.quality,
    metrics: {
      promptCharacters: prompt.reduce((sum, message) => sum + message.content.length, 0),
      completionCharacters: completion.length,
      messageCount: candidate.messages.length,
    },
  };
}

function dedupeCandidates(candidates: readonly Candidate[]): { records: CanonicalTrainingRecord[]; duplicateCount: number } {
  const seen = new Set<string>();
  const records: CanonicalTrainingRecord[] = [];
  let duplicateCount = 0;
  for (const candidate of candidates) {
    const record = canonicalRecord(candidate);
    const fingerprint = JSON.stringify(record.messages.map((message) => [message.role, message.content.trim()]));
    if (seen.has(fingerprint)) {
      duplicateCount += 1;
      continue;
    }
    seen.add(fingerprint);
    records.push(record);
  }
  return { records, duplicateCount };
}

function preferencePairs(records: readonly CanonicalTrainingRecord[]) {
  const groups = new Map<string, CanonicalTrainingRecord[]>();
  for (const record of records) {
    if (!record.quality.scored || record.source.type !== "session") continue;
    const key = JSON.stringify(record.prompt);
    groups.set(key, [...(groups.get(key) ?? []), record]);
  }
  const pairs: Array<{ prompt: TrainingMessage[]; chosen: string; rejected: string }> = [];
  for (const group of groups.values()) {
    const accepted = group.filter((record) => record.quality.status === "accepted");
    const rejected = group.filter((record) => record.quality.status === "rejected");
    for (const chosen of accepted) {
      for (const bad of rejected) pairs.push({ prompt: chosen.prompt, chosen: chosen.completion, rejected: bad.completion });
    }
  }
  return pairs;
}

function fullConversation(
  session: LearnerSession,
  latestFeedback: ReadonlyMap<string, LearnerFeedbackEvent>,
  minimumAssistantCharacters: number,
  redact: boolean,
): TrainingMessage[] {
  const messages: TrainingMessage[] = [];
  let pendingUser: LearnerMessage | undefined;
  for (const message of session.messages) {
    if (message.role === "system" && message.content.trim()) {
      messages.push({ role: "system", content: redactText(message.content.trim(), redact).text });
    } else if (message.role === "user") {
      pendingUser = message;
    } else if (message.role === "assistant" && pendingUser) {
      const quality = qualityForFeedback(latestFeedback.get(message.id));
      if (message.content.trim().length >= minimumAssistantCharacters && quality.status !== "rejected") {
        messages.push(
          { role: "user", content: redactText(pendingUser.content.trim(), redact).text },
          { role: "assistant", content: redactText(message.content.trim(), redact).text },
        );
      }
      pendingUser = undefined;
    }
  }
  return messages;
}

export function buildNativeFineTuneExport(
  data: PortableLearnerData,
  options: NativeFineTuneExportOptions = {},
): NativeFineTuneExportResult {
  const redact = options.redact ?? true;
  const minimumAssistantCharacters = Math.max(1, Math.floor(options.minimumAssistantCharacters ?? 24));
  const now = options.now ?? new Date();
  const counters = { skipped: 0, redactions: 0 };
  const candidates: Candidate[] = [];
  const latestFeedback = feedbackByMessage(data.feedbackEvents);

  for (const artifact of data.artifacts) {
    const content = artifact.content?.trim();
    if (!content) {
      counters.skipped += 1;
      continue;
    }
    const redacted = redactText(content, redact);
    counters.redactions += redacted.count;
    const instruction = artifactInstruction(artifact.kind, artifact.title);
    candidates.push({
      id: `artifact-${safeId(artifact.kind)}-${safeId(artifact.id)}`,
      source: { type: "artifact", kind: artifact.kind, topic: artifact.title },
      messages: [{ role: "user", content: instruction }, { role: "assistant", content: redacted.text }],
      quality: { status: "accepted", recommendedForSft: true, scored: false },
    });
  }
  for (const session of data.sessions) {
    candidates.push(...sessionCandidates(session, latestFeedback, minimumAssistantCharacters, redact, counters));
  }

  const deduplicated = dedupeCandidates(candidates);
  const records = deduplicated.records;
  const sft = records.filter((record) => record.quality.status !== "rejected" && record.quality.status !== "reference");
  const scored = records.filter((record) => record.source.type === "session" && record.quality.scored);
  const pairs = preferencePairs(records);
  const chatml: Array<{
    messages: TrainingMessage[];
    keating: {
      source: string;
      title: string;
      sessionId?: string;
      model?: LearnerSession["model"];
      training: { id: string; kind: string; topic?: string };
    };
  }> = data.sessions.flatMap((session) => {
    const messages = fullConversation(session, latestFeedback, minimumAssistantCharacters, redact);
    if (!messages.some((message) => message.role === "user") || !messages.some((message) => message.role === "assistant")) return [];
    return [{
      messages,
      keating: {
        source: "keating-session-export",
        title: session.title,
        sessionId: session.id,
        model: session.model,
        training: { id: `session-${safeId(session.id)}`, kind: "conversation", topic: session.title },
      },
    }];
  });
  for (const record of sft.filter((candidate) => candidate.source.type === "artifact")) {
    chatml.push({
      messages: record.messages,
      keating: {
        source: "keating-training-export",
        title: record.source.topic ?? record.source.kind,
        training: { id: record.id, kind: record.source.kind, topic: record.source.topic },
      },
    });
  }

  const quality = { accepted: 0, unscored: 0, review: 0, rejected: 0, reference: 0 };
  for (const record of records) quality[record.quality.status] += 1;
  const trainRecords = records.filter((record) => record.split === "train").length;
  const kto = scored.map((record) => ({ prompt: record.prompt, completion: record.completion, label: record.quality.status === "accepted" }));
  const grpo = [...new Map(records.map((record) => [JSON.stringify(record.prompt), { prompt: record.prompt }])).values()];
  const manifest = {
    schemaVersion: 2,
    mode: "finetune",
    generatedAt: now.toISOString(),
    source: "all",
    format: "both",
    redactionEnabled: redact,
    minimumAssistantCharacters,
    judgeScoringEnabled: false,
    recommendedDataset: "data/keating.training.jsonl",
    splitStrategy: "Stable source-group hash (90% train / 10% validation)",
    counts: {
      artifactsRead: data.artifacts.length,
      sessionsRead: data.sessions.length,
      sandboxFilesRead: 0,
      sandboxCommitsRead: 0,
      examplesWritten: sft.length,
      canonicalRecords: records.length,
      trainRecords,
      validationRecords: records.length - trainRecords,
      sftExcluded: records.length - sft.length,
      duplicatesRemoved: deduplicated.duplicateCount,
      skipped: counters.skipped,
      redactions: counters.redactions,
      rewardedLines: scored.length,
      ktoLines: kto.length,
      preferenceLines: pairs.length,
      dpoTextLines: pairs.length,
      grpoPromptLines: grpo.length,
    },
    quality,
    rewardStats: {
      scored: scored.length,
      unscored: records.filter((record) => record.source.type === "session" && !record.quality.scored).length,
      bySource: { explicit: scored.length, inferred: 0, quiz: 0, judge: 0 },
    },
    warnings: [
      ...(sft.length === 0 ? ["No supervised fine-tuning examples were generated."] : []),
      ...(quality.unscored > 0 ? [`${quality.unscored} captured responses have no quality signal; review them before high-stakes training.`] : []),
      ...(pairs.length === 0 ? ["No explicit chosen/rejected response pairs were available, so DPO files are omitted."] : []),
      "Pattern-based redaction cannot guarantee removal of every personal or confidential value; inspect the canonical dataset before sharing.",
    ],
  };

  return {
    canonicalJsonl: toJsonl(records),
    chatmlJsonl: toJsonl(chatml),
    alpacaJsonl: toJsonl(sft.map((record) => ({
      instruction: record.prompt.at(-1)?.content ?? "",
      input: "",
      output: record.completion,
    }))),
    rewardedJsonl: toJsonl(scored.map((record) => ({
      id: record.id,
      sessionId: record.source.sessionId,
      topic: record.source.topic,
      messageTimestamp: record.source.messageTimestamp,
      messages: record.messages,
      reward: record.quality.reward,
      signals: record.quality.signals,
      scored: true,
    }))),
    ktoJsonl: toJsonl(kto),
    preferenceJsonl: toJsonl(pairs),
    dpoTextJsonl: toJsonl(pairs.map((pair) => ({
      prompt: pair.prompt.map((message) => `${message.role}: ${message.content}`).join("\n\n"),
      chosen: pair.chosen,
      rejected: pair.rejected,
    }))),
    grpoPromptsJsonl: toJsonl(grpo),
    manifestJson: `${JSON.stringify(manifest, null, 2)}\n`,
    recordCount: records.length,
    exampleCount: sft.length,
    skippedCount: counters.skipped,
    redactionCount: counters.redactions,
  };
}

import { strToU8, zipSync } from "fflate";
import type { NativeFineTuneExportResult } from "./training-export";

interface TrainingFile {
  path: string;
  purpose: string;
  content: string;
  records?: number;
}

export interface NativeTrainingArchive {
  bytes: Uint8Array;
  filename: string;
  files: Array<Omit<TrainingFile, "content">>;
}

function lineCount(content: string | undefined): number {
  return content?.trim() ? content.trim().split("\n").length : 0;
}

function addJsonl(files: TrainingFile[], path: string, purpose: string, content: string | undefined): void {
  if (!content) return;
  files.push({ path, purpose, content, records: lineCount(content) });
}

function canonicalSchema(): string {
  return `${JSON.stringify({
    $schema: "https://json-schema.org/draft/2020-12/schema",
    type: "object",
    additionalProperties: false,
    required: ["schemaVersion", "id", "split", "task", "source", "messages", "prompt", "completion", "quality", "metrics"],
    properties: {
      schemaVersion: { const: 2 },
      id: { type: "string", minLength: 1 },
      split: { enum: ["train", "validation"] },
      task: { enum: ["supervised-finetuning", "preference-learning", "reference"] },
      source: { type: "object" },
      messages: { type: "array", minItems: 2 },
      prompt: { type: "array", minItems: 1 },
      completion: { type: "string", minLength: 1 },
      quality: { type: "object" },
      metrics: { type: "object" },
    },
  }, null, 2)}\n`;
}

function buildReadme(manifest: Record<string, any>, files: readonly TrainingFile[]): string {
  const counts = manifest.counts ?? {};
  const quality = manifest.quality ?? {};
  const rows = files.map((file) => `| \`${file.path}\` | ${file.records ?? "n/a"} | ${file.purpose} |`).join("\n");
  return `# Keating training export

Start with \`data/keating.training.jsonl\`. It preserves source provenance, prompt context, model identity, explicit quality signals, deterministic split assignment, and character counts. Compatibility files are derived views.

## Dataset summary

- Generated: ${manifest.generatedAt ?? "unknown"}
- Canonical records: ${counts.canonicalRecords ?? 0}
- SFT-compatible examples: ${counts.examplesWritten ?? 0}
- Train / validation: ${counts.trainRecords ?? 0} / ${counts.validationRecords ?? 0}
- Exact duplicates removed: ${counts.duplicatesRemoved ?? 0}
- Responses excluded from SFT: ${counts.sftExcluded ?? 0}
- Redactions applied: ${counts.redactions ?? 0}

## Quality labels

- \`accepted\` (${quality.accepted ?? 0}): explicit helpful feedback or a learner-authored artifact; suitable for SFT review.
- \`unscored\` (${quality.unscored ?? 0}): captured without a quality claim; review before training.
- \`rejected\` (${quality.rejected ?? 0}): explicit missed feedback; excluded from positive SFT and retained for KTO/preference learning.
- \`review\` (${quality.review ?? 0}) and \`reference\` (${quality.reference ?? 0}): retained for inspection, not recommended as positive SFT.

## Files

| Path | Records | Use |
| --- | ---: | --- |
${rows}

## Recommended workflow

1. Validate the canonical JSONL against the bundled schema.
2. Review every record whose \`quality.recommendedForSft\` is false.
3. Use ChatML or Alpaca only after reviewing unscored completions.
4. Use KTO and DPO files only where explicit feedback supports the label or preference.
5. Keep source groups in their assigned split to reduce leakage.

## Privacy

Redaction was ${manifest.redactionEnabled ? "enabled" : "disabled"}. Pattern matching cannot guarantee removal of every personal or confidential value. Inspect the canonical file before sharing or uploading it.
`;
}

function archiveTimestamp(generatedAt: unknown): string {
  const date = typeof generatedAt === "string" ? new Date(generatedAt) : new Date();
  return (Number.isNaN(date.getTime()) ? new Date() : date).toISOString().replace(/[:.]/g, "-");
}

export function buildNativeTrainingArchive(result: NativeFineTuneExportResult): NativeTrainingArchive {
  const manifest = JSON.parse(result.manifestJson) as Record<string, any>;
  const files: TrainingFile[] = [];
  addJsonl(files, "data/keating.training.jsonl", "Canonical provenance-rich records; start here.", result.canonicalJsonl);
  addJsonl(files, "data/sft/train.chatml.jsonl", "ChatML compatibility data for supervised fine-tuning.", result.chatmlJsonl);
  addJsonl(files, "data/sft/train.alpaca.jsonl", "Alpaca compatibility data for supervised fine-tuning.", result.alpacaJsonl);
  addJsonl(files, "data/rewards/train.rewarded.jsonl", "Explicitly scored per-turn rewards.", result.rewardedJsonl);
  addJsonl(files, "data/preferences/train.kto.jsonl", "Explicit desirable and undesirable KTO examples.", result.ktoJsonl);
  addJsonl(files, "data/preferences/train.dpo.chat.jsonl", "Explicit chosen/rejected chat preference pairs.", result.preferenceJsonl);
  addJsonl(files, "data/preferences/train.dpo.text.jsonl", "Text-prompt DPO compatibility pairs.", result.dpoTextJsonl);
  addJsonl(files, "data/rl/prompts.grpo.jsonl", "Unique prompt contexts for GRPO-style generation.", result.grpoPromptsJsonl);
  files.push({
    path: "schemas/keating-training-record.schema.json",
    purpose: "JSON Schema for each canonical JSONL record.",
    content: canonicalSchema(),
  });
  files.unshift({ path: "README.md", purpose: "Dataset card and training guidance.", content: buildReadme(manifest, files) });
  const catalog = files.map(({ path, purpose, records }) => ({ path, purpose, records }));
  const enrichedManifest = { ...manifest, files: [{ path: "manifest.json", purpose: "Machine-readable export manifest." }, ...catalog] };
  files.unshift({
    path: "manifest.json",
    purpose: "Machine-readable export settings, counts, quality summary, and file catalog.",
    content: `${JSON.stringify(enrichedManifest, null, 2)}\n`,
  });
  return {
    bytes: zipSync(Object.fromEntries(files.map((file) => [file.path, strToU8(file.content)])), { level: 6 }),
    filename: `keating-training-${archiveTimestamp(manifest.generatedAt)}.zip`,
    files: files.map(({ content: _content, ...file }) => file),
  };
}
import { File, Paths } from "expo-file-system";
import * as Sharing from "expo-sharing";
import type { NativeTrainingArchive } from "./training-archive";

export async function shareNativeTrainingArchive(archive: NativeTrainingArchive): Promise<void> {
  if (!await Sharing.isAvailableAsync()) {
    throw new Error("Sharing is not available on this device. Export from a device that supports the system share sheet.");
  }
  const file = new File(Paths.cache, archive.filename);
  try {
    file.create({ intermediates: true, overwrite: true });
    file.write(archive.bytes);
    await Sharing.shareAsync(file.uri, {
      mimeType: "application/zip",
      dialogTitle: "Export Keating fine-tuning data",
    });
  } catch (error) {
    if (error instanceof Error && error.message.startsWith("Sharing is not available")) throw error;
    throw new Error("Keating could not prepare the fine-tuning archive. Check device storage and try again.");
  } finally {
    try {
      if (file.exists) file.delete();
    } catch {
      // Cleanup cannot turn a completed share into a false failure.
    }
  }
}
import { useMemo, useState } from "react";
import { Pressable, StyleSheet, Text, View } from "react-native";
import Svg, { Circle, Line, Path, Text as SvgText } from "react-native-svg";
import type { BenchmarkHistoryRecord, EvolutionHistoryRecord } from "@keating/learner-contracts";
import { radii, spacing, useKeatingTheme } from "@/constants/theme";
import { buildEvaluationTrend, evaluationPath } from "@/lib/evaluation-history";

interface Props {
  benchmarks: readonly BenchmarkHistoryRecord[];
  evolutions: readonly EvolutionHistoryRecord[];
}

export function SelfEvolutionChart({ benchmarks, evolutions }: Props) {
  const theme = useKeatingTheme();
  const styles = createStyles(theme);
  const trend = useMemo(() => buildEvaluationTrend(benchmarks, evolutions), [benchmarks, evolutions]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const selected = trend.points.find((point) => point.id === selectedId);
  const recentEvolutions = [...evolutions]
    .sort((left, right) => right.createdAt.localeCompare(left.createdAt) || right.id.localeCompare(left.id))
    .slice(0, 6);

  if (!trend.points.length) {
    return <Text style={styles.empty}>No self-evolution records yet. Run a benchmark or evolution on web or in the Keating runtime, then import or sync that portable history.</Text>;
  }

  return (
    <View>
      <View style={styles.metrics}>
        <Metric label="Latest benchmark" value={trend.latestBenchmark?.score.toFixed(1) ?? "none"} styles={styles} />
        <Metric label="Latest evolution" value={trend.latestEvolution?.bestScore.toFixed(1) ?? "none"} styles={styles} />
        <Metric label="Recorded runs" value={String(trend.points.length)} styles={styles} />
      </View>
      {!trend.hasMeaningfulScores ? (
        <Text style={styles.notice}>Scores are recorded, but they are all 0.0. Do not treat this as a trend until a later run records a meaningful score.</Text>
      ) : (
        <View accessible accessibilityRole="image" accessibilityLabel={`Self-evolution score trend with ${benchmarks.length} benchmark and ${evolutions.length} evolution runs`}>
          <Svg width="100%" height={150} viewBox="0 0 320 150">
            {[0, 25, 50, 75, 100].map((score) => {
              const y = 122 - (score / 100) * 112;
              return <ViewBoxLine key={score} score={score} y={y} color={theme.colors.border} muted={theme.colors.textMuted} />;
            })}
            {trend.benchmarkPoints.length > 1 ? <Path d={evaluationPath(trend.benchmarkPoints)} fill="none" stroke="#6366f1" strokeWidth={2} /> : null}
            {trend.evolutionPoints.length > 1 ? <Path d={evaluationPath(trend.evolutionPoints)} fill="none" stroke="#22c55e" strokeWidth={2} /> : null}
            {trend.points.map((point) => (
              <Circle
                key={`${point.kind}:${point.id}`}
                cx={point.x}
                cy={point.y}
                r={selectedId === point.id ? 6 : 4}
                fill={point.kind === "benchmark" ? "#6366f1" : "#22c55e"}
                stroke={theme.colors.surface}
                strokeWidth={2}
                onPress={() => setSelectedId(point.id)}
              />
            ))}
          </Svg>
        </View>
      )}
      <View style={styles.legend}>
        <Legend color="#6366f1" label="Benchmark scores" styles={styles} />
        <Legend color="#22c55e" label="Evolved policy scores" styles={styles} />
      </View>
      {selected ? (
        <Text accessibilityLiveRegion="polite" style={styles.selection}>
          {selected.kind === "benchmark" ? "Benchmark" : "Evolution"} score {selected.score.toFixed(2)} · {formatDate(selected.createdAt)}
        </Text>
      ) : null}
      {recentEvolutions.length ? (
        <View style={styles.history}>
          {recentEvolutions.map((evolution) => (
            <Pressable
              key={evolution.id}
              onPress={() => setSelectedId(evolution.id)}
              accessibilityRole="button"
              accessibilityLabel={`Evolution ${evolution.topic ?? "General teaching policy"}, score ${evolution.bestScore.toFixed(2)}`}
              style={({ pressed }) => [styles.historyRow, pressed && styles.pressed]}
            >
              <Text style={styles.historyTitle}>{evolution.topic ?? "General teaching policy"}</Text>
              <Text style={styles.historyMeta}>Score {evolution.bestScore.toFixed(2)} · {formatDate(evolution.createdAt)}</Text>
              <Text numberOfLines={2} style={styles.policy}>{evolution.policy}</Text>
            </Pressable>
          ))}
        </View>
      ) : null}
    </View>
  );
}

function ViewBoxLine({ score, y, color, muted }: { score: number; y: number; color: string; muted: string }) {
  return <>
    <Line x1={28} y1={y} x2={310} y2={y} stroke={color} strokeWidth={1} />
    <SvgText x={0} y={y + 4} fontSize={10} fill={muted}>{score}</SvgText>
  </>;
}

function Metric({ label, value, styles }: { label: string; value: string; styles: ReturnType<typeof createStyles> }) {
  return <View style={styles.metric}><Text style={styles.metricLabel}>{label}</Text><Text style={styles.metricValue}>{value}</Text></View>;
}

function Legend({ color, label, styles }: { color: string; label: string; styles: ReturnType<typeof createStyles> }) {
  return <View style={styles.legendItem}><View style={[styles.swatch, { backgroundColor: color }]} /><Text style={styles.legendText}>{label}</Text></View>;
}

function formatDate(value: string): string {
  return new Intl.DateTimeFormat(undefined, { month: "short", day: "numeric", year: "numeric" }).format(Date.parse(value));
}

function createStyles(theme: ReturnType<typeof useKeatingTheme>) {
  const { colors, type } = theme;
  return StyleSheet.create({
