 16	    });
 17	  } catch (error) {
 18	    if (error instanceof Error && error.message.startsWith("Sharing is not available")) throw error;
 19	    throw new Error("Keating could not prepare the fine-tuning archive. Check device storage and try again.");
 20	  } finally {
 21	    try {
 22	      if (file.exists) file.delete();
 23	    } catch {
 24	      // Cleanup cannot turn a completed share into a false failure.
 25	    }
 26	  }
