125	    "SELECT value FROM repository_meta WHERE key = ?;",
126	    "schema_version",
127	  );
128	  if (!existing) {
129	    await transaction.runAsync(
130	      "INSERT INTO repository_meta (key, value) VALUES (?, ?);",
