137	  const stored = parseStoredSchemaVersion(existing.value);
138	  if (stored === null) throw new Error("Learner repository schema metadata is invalid.");
139	  if (stored > LEARNER_REPOSITORY_SCHEMA_VERSION) {
140	    throw new Error("Learner repository was created by a newer app version.");
141	  }
142	  if (stored < 1) {
143	    throw new Error("Learner repository schema migration is required.");
144	  }
145	  return stored;
