    76	  async getFirstAsync<T>(source: string, ...params: SqlBindValue[]): Promise<T | null> {
    77	    return this.getFirstFromJournal(source, params, this.journal);
    78	  }
    79	
    80	  async getAllAsync<T>(_source: string, ..._params: SqlBindValue[]): Promise<T[]> {
    81	    return [];
    82	  }
