    84	  private async getFirstFromJournal<T>(
    85	    source: string,
    86	    params: SqlBindValue[],
    87	    journal: ReadonlyMap<string, JournalRow>,
    88	  ): Promise<T | null> {
    89	    this.calls.push(`get:${source}`);
    90	    if (source.includes("FROM repository_meta")) {
    91	      const value = this.meta.get(String(params[0]));
    92	      return value === undefined ? null : { value } as T;
    93	    }
    94	    if (source.includes("FROM migration_journal")) {
    95	      const row = journal.get(String(params[0]));
    96	      return row ? { ...row } as T : null;
    97	    }
    98	    return null;
    99	  }
