   101	  async withExclusiveTransactionAsync(task: (transaction: AsyncSqlExecutor) => Promise<void>): Promise<void> {
   102	    this.exclusiveTransactions += 1;
   103	    const previous = this.transactionTail;
   104	    let release!: () => void;
   105	    this.transactionTail = new Promise<void>((resolve) => {
   106	      release = resolve;
   107	    });
   108	    await previous;
   109	    const journalSnapshot = new Map(
   110	      [...this.journal].map(([id, row]) => [id, { ...row }]),
   111	    );
   112	    const transaction: AsyncSqlExecutor = {
   113	      execAsync: (source) => this.execAsync(source),
   114	      runAsync: (source, ...params) => this.runAsync(source, ...params),
   115	      getFirstAsync: <T>(source: string, ...params: SqlBindValue[]) =>
   116	        this.getFirstFromJournal<T>(source, params, journalSnapshot),
   117	      getAllAsync: <T>(_source: string, ..._params: SqlBindValue[]) => Promise.resolve([] as T[]),
   118	    };
   119	    try {
   120	      await task(transaction);
   121	    } finally {
   122	      release();
   123	    }
   124	  }
   125	
   126	  async closeAsync(): Promise<void> {
   127	    this.closeCalls += 1;
   128	  }
   129	}
