   339	function addSandboxExamples(
   340		examples: FineTuneExample[],
   341		sandbox: KeatingSandboxPortableBundle | undefined,
   342		options: WebFineTuneExportOptions,
   343		counters: { redactions: number; skipped: number },
   344		conversations?: WebConversation[],
   345	): { filesRead: number; commitsRead: number } {
   346		if (!sandbox) return { filesRead: 0, commitsRead: 0 };
   347		let filesRead = 0;
   348		const commitsRead = sandbox.vc.commits.length;
   349		for (const file of sandbox.nodepod.files) {
   350			filesRead += 1;
   351			if (!/\/workspace\/(src\/core\/|pi\/prompts\/|web\/src\/keating\/)/.test(file.path)) continue;
   352			const content = file.content.trim();
   353			if (!content) {
   354				counters.skipped += 1;
   355				continue;
   356			}
   357			const redacted = redactText(content, options.redact);
   358			counters.redactions += redacted.count;
   359			const instruction = `Maintain or improve this Keating sandbox source file: ${file.path}.`;
   360			const messages = [
   361				{ role: "user" as const, content: instruction },
   362				{ role: "assistant" as const, content: redacted.text },
   363			];
   364			examples.push({
   365				id: `sandbox-file-${planSafeId(file.path)}`,
   366				source: "sandbox",
   367				kind: "source-file",
   368				path: file.path,
   369				instruction,
   370				output: redacted.text,
   371				messages,
   372			});
   373			conversations?.push({ source: "sandbox", messages });
   374		}
   375		for (const commit of sandbox.vc.commits) {
   376			const files = commit.files
   377				.map((file) => `${file.path} ${file.hash}`)
   378				.join("\n");
   379			const summary = `Commit: ${commit.message}\nBranch: ${commit.branchId}\nFiles:\n${files}`.trim();
   380			if (!files) {
   381				counters.skipped += 1;
   382				continue;
   383			}
   384			const redacted = redactText(summary, options.redact);
   385			counters.redactions += redacted.count;
   386			const instruction = `Describe the purpose and exact file impact of the Keating sandbox checkpoint: ${commit.message}`;
   387			const messages = [
   388				{ role: "user" as const, content: instruction },
   389				{ role: "assistant" as const, content: redacted.text },
   390			];
   391			examples.push({
   392				id: `sandbox-commit-${planSafeId(commit.id)}`,
