   430	function stableHash(value: string): number {
   431		let hash = 0x811c9dc5;
   432		for (let index = 0; index < value.length; index += 1) {
   433			hash ^= value.charCodeAt(index);
   434			hash = Math.imul(hash, 0x01000193);
   435		}
   436		return hash >>> 0;
   437	}
