   451			? "accepted"
   452			: turn.reward <= 0.35
   453				? "rejected"
   454				: "review";
   455		return {
   456			status,
   457			recommendedForSft: status === "accepted",
   458			scored: true,
   459			reward: turn.reward,
   460			signals: turn.signals,
   461		};
