   474		const seen = new Set<string>();
   475		const records: CanonicalTrainingRecord[] = [];
   476		let duplicateCount = 0;
   477		for (const example of examples) {
   478			const turnKey = rewardTurnKey(example.sessionId, example.messageTimestamp);
   479			const turn = turnKey ? turnsByKey.get(turnKey) : undefined;
   480			const rawMessages = turn
   481				? [...turn.context, { role: "assistant" as const, content: turn.completion }]
   482				: (example.messages ?? [
   483					{ role: "user" as const, content: example.instruction },
   484					{ role: "assistant" as const, content: example.output },
   485				]);
   486			const baseMessages = rawMessages.map((message) => ({ role: message.role, content: message.content }));
   487			const messages = !turn && example.source === "session" && persona.trim()
   488				? [{ role: "system" as const, content: persona.trim() }, ...baseMessages]
   489				: baseMessages;
   490			const completion = messages.at(-1)?.content ?? example.output;
   491			const prompt = messages.slice(0, -1);
   492			const fingerprint = JSON.stringify([...prompt.map((message) => [message.role, message.content.trim()]), ["assistant", completion.trim()]]);
   493			if (seen.has(fingerprint)) {
   494				duplicateCount += 1;
   495				continue;
   496			}
   497			seen.add(fingerprint);
   498			const quality = example.source === "sandbox"
   499				? { status: "reference" as const, recommendedForSft: false, scored: false }
   500				: example.source === "artifact"
   501					? { status: "accepted" as const, recommendedForSft: true, scored: false }
   502					: qualityForTurn(turn);
   503			records.push({
   504				schemaVersion: 2,
   505				id: `${example.id}-${stableHash(fingerprint).toString(36)}`,
   506				split: splitFor(example.sessionId ?? example.path ?? example.commitId ?? example.id),
   507				task: quality.status === "rejected" ? "preference-learning" : quality.status === "reference" ? "reference" : "supervised-finetuning",
   508				source: {
   509					type: example.source,
   510					kind: example.kind,
   511					topic: example.topic,
   512					sessionId: example.sessionId,
   513					sessionTitle: example.sessionTitle,
   514					messageTimestamp: example.messageTimestamp,
   515					model: example.model,
   516					thinkingLevel: example.thinkingLevel,
   517					path: example.path,
   518					commitId: example.commitId,
   519				},
   520				messages,
   521				prompt,
   522				completion,
   523				quality,
   524				metrics: {
   525					promptCharacters: prompt.reduce((sum, message) => sum + message.content.length, 0),
   526					completionCharacters: completion.length,
   527					messageCount: messages.length,
   528				},
   529			});
   530		}
   531		return { records, duplicateCount };
   532	}
