   534	function dedupeExamples(examples: FineTuneExample[]): { examples: FineTuneExample[]; duplicateCount: number } {
   535		const seen = new Set<string>();
   536		const unique: FineTuneExample[] = [];
   537		let duplicateCount = 0;
   538		for (const example of examples) {
   539			const fingerprint = JSON.stringify([
   540				example.instruction.trim(),
   541				(example.input ?? "").trim(),
   542				example.output.trim(),
   543			]);
   544			if (seen.has(fingerprint)) {
   545				duplicateCount += 1;
   546				continue;
   547			}
   548			seen.add(fingerprint);
   549			unique.push(example);
   550		}
   551		return { examples: unique, duplicateCount };
   552	}
