   554	function qualityCounts(records: CanonicalTrainingRecord[]): Record<TrainingQualityStatus, number> {
   555		const counts: Record<TrainingQualityStatus, number> = {
   556			accepted: 0,
   557			unscored: 0,
   558			review: 0,
   559			rejected: 0,
   560			reference: 0,
   561		};
   562		for (const record of records) counts[record.quality.status] += 1;
   563		return counts;
   564	}
